import type { FrameworkApiReference } from '../types'
import { liveKitAgentsLearningMeta } from './learning-meta'

const ROOT = 'https://docs.livekit.io/reference/python/livekit/agents/index.html'
const LLM = 'https://docs.livekit.io/reference/python/livekit/agents/llm/index.html'
const STT = 'https://docs.livekit.io/reference/python/livekit/agents/stt/index.html'
const TTS = 'https://docs.livekit.io/reference/python/livekit/agents/tts/index.html'
const VAD = 'https://docs.livekit.io/reference/python/livekit/agents/vad.html'
const METRICS = 'https://docs.livekit.io/reference/python/livekit/agents/metrics/index.html'

type LessonInput = {
  slug: string
  name: string
  group: string
  kind: FrameworkApiReference['kind']
  signature: string
  purpose: string
  scenario: string
  example: string
  result: string
  principle: string
  risk: string
  url: string
  maturity?: FrameworkApiReference['maturity']
}

function lesson(input: LessonInput): FrameworkApiReference {
  const learningMeta = liveKitAgentsLearningMeta[input.name as keyof typeof liveKitAgentsLearningMeta]
  if (!learningMeta) throw new Error(`Missing structured LiveKit Agents learning metadata for ${input.name}`)
  return {
    slug: `livekit-agents-${input.slug}`,
    technologySlug: 'livekit-agents',
    name: input.name,
    group: input.group,
    kind: input.kind,
    maturity: input.maturity ?? 'stable',
    signature: input.signature,
    beginner: `${input.purpose}。初学者可以先把它放进“${input.group}”这条主链路理解，不需要先掌握框架内部的媒体调度实现。`,
    whenToUse: `${input.scenario}；如果只是读取结果而不需要改变这层行为，就优先沿用 AgentSession 的默认编排。`,
    example: input.example,
    exampleLanguage: 'py',
    returns: `${input.result}。异步方法必须 await；流式对象则需要迭代或显式关闭，不能把创建对象误当成处理已经完成。`,
    interview: `${input.principle}。面试时要说明它处在实时链路的哪一层、由谁驱动、何时产生背压或事件，而不只是背方法名。`,
    pitfall: `${input.risk}。生产环境还要同时考虑超时、取消、资源关闭、敏感日志与可观测性，避免实时会话留下悬挂任务。`,
    officialUrl: input.url,
    ...learningMeta,
  }
}

const root = (anchor: string) => `${ROOT}#livekit.agents.${anchor}`
const llm = (anchor: string) => `${LLM}#livekit.agents.llm.${anchor}`
const stt = (anchor: string) => `${STT}#livekit.agents.stt.${anchor}`
const tts = (anchor: string) => `${TTS}#livekit.agents.tts.${anchor}`
const vad = (anchor: string) => `${VAD}#livekit.agents.vad.${anchor}`
const metrics = (anchor: string) => `${METRICS}#livekit.agents.metrics.${anchor}`

/**
 * Learner-facing denominator (verified against the official Python reference):
 * 103 public symbols an application author directly constructs, calls, overrides,
 * configures, or subscribes to: Agent/AgentSession 25, Worker/Job 15, Room I/O 10,
 * LLM/tools 14, STT/VAD 10, TTS 6, events/metrics 14, realtime 6, turn handling 3.
 * Internal implementation classes, provider-plugin implementations, CLI/Cloud
 * deployment APIs, deprecated compatibility aliases, and passive data fields are
 * deliberately outside this teaching denominator.
 */
export const LIVEKIT_FRAMEWORK_API_EXPECTED_COUNT = 103

